export type GalleryItem = {
  id: string;
  year: number;
  place: string;
  title: string;
  /** Generated by scripts/make-placeholders.mjs. */
  src: string;
};

// The two axes of the grid: wheel moves along years, arrows along places.
// Keep in sync with scripts/make-placeholders.mjs.
export const years = [1996, 2008, 2020, 2026];
export const places = ['Busan', 'Seoul', 'Somewhere'];

const titles: Record<string, string> = {
  '1996-Busan': 'Salt Wind',
  '1996-Seoul': 'Paper Map',
  '1996-Somewhere': 'Unlabelled Roll',
  '2008-Busan': 'Ferry Terminal',
  '2008-Seoul': 'Night Bus',
  '2008-Somewhere': 'Borrowed Room',
  '2020-Busan': 'Empty Platform',
  '2020-Seoul': 'Window Desk',
  '2020-Somewhere': 'Screen Light',
  '2026-Busan': 'Second Coast',
  '2026-Seoul': 'Late Studio',
  '2026-Somewhere': 'Still Unnamed',
};

// One card per (year, place) pair — 4 x 3 = 12.
export const items: GalleryItem[] = years.flatMap((year) =>
  places.map((place) => ({
    id: `${year}-${place}`,
    year,
    place,
    title: titles[`${year}-${place}`],
    src: `/placeholders/${year}-${place.toLowerCase()}.svg`,
  })),
);
